use vstd::prelude::*;
verus! {

    /// Given a non-empty vector of 8-bit signed integers `x`, returns a new vector `result`
    /// of the same length where each element classifies the sign of the corresponding
    /// element in `x`:
    ///   - -1 if the element is < 0
    ///   -  0 if the element is == 0
    ///   -  1 if the element is > 0
    pub proof fn sign(x: Vec<i8>) -> (result: Vec<i8>)
        requires
            x.len() > 0,
        ensures
            result.len() == x.len(),
        ensures
            forall |j: usize|
                j < x.len() ==>
                (
                    if x[j] < 0 {
                        result[j] == -1
                    } else if x[j] == 0 {
                        result[j] == 0
                    } else {
                        result[j] == 1
                    }
                ),
    {
        let mut result: Vec<i8> = Vec::new();
        let mut i: usize = 0;

        // We loop from 0 to x.len(), pushing the sign of x[i] into result.
        while i < x.len() {
            invariant
                0 <= i && i <= x.len(),
            invariant
                result.len() == i,
            invariant
                forall |j: usize|
                    j < i ==>
                    (
                        if x[j] < 0 {
                            result[j] == -1
                        } else if x[j] == 0 {
                            result[j] == 0
                        } else {
                            result[j] == 1
                        }
                    ),
            decreases
                x.len() - i;

            let xi = x[i];
            let si: i8 = if xi < 0 {
                -1
            } else if xi == 0 {
                0
            } else {
                1
            };
            result.push(si);
            i += 1;
        }

        result
    }
}